import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { getSchemaGraph } from '../services/api';

const SchemaGraph = () => {
  const svgRef = useRef(null);
  const containerRef = useRef(null);
  const [graphData, setGraphData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedNode, setSelectedNode] = useState(null);
  const [dimensions, setDimensions] = useState({ width: 800, height: 600 });

  useEffect(() => {
    const fetchGraph = async () => {
      try {
        const response = await getSchemaGraph();
        if (response.success) {
          setGraphData(response.data);
        }
      } catch (err) {
        setError('Failed to load schema graph');
      } finally {
        setLoading(false);
      }
    };

    fetchGraph();
  }, []);

  useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        setDimensions({
          width: containerRef.current.clientWidth,
          height: 600,
        });
      }
    };

    updateDimensions();
    window.addEventListener('resize', updateDimensions);
    return () => window.removeEventListener('resize', updateDimensions);
  }, []);

  useEffect(() => {
    if (!graphData || !svgRef.current) return;

    const { width, height } = dimensions;
    const svg = d3.select(svgRef.current);

    // Clear previous content
    svg.selectAll('*').remove();

    // Create container group for zoom
    const g = svg.append('g');

    // Add zoom behavior
    const zoom = d3.zoom()
      .scaleExtent([0.3, 3])
      .on('zoom', (event) => {
        g.attr('transform', event.transform);
      });

    svg.call(zoom);

    // Color scale based on complexity (fan-in + fan-out)
    const complexityScale = d3.scaleLinear()
      .domain([0, d3.max(graphData.nodes, d => d.fanIn + d.fanOut)])
      .range([0, 1]);

    const colorScale = d3.scaleSequential(d3.interpolateYlOrRd);

    // Size scale based on fan-in
    const sizeScale = d3.scaleLinear()
      .domain([0, d3.max(graphData.nodes, d => d.fanIn)])
      .range([20, 50]);

    // Create force simulation
    const simulation = d3.forceSimulation(graphData.nodes)
      .force('link', d3.forceLink(graphData.edges)
        .id(d => d.id)
        .distance(150)
        .strength(0.5))
      .force('charge', d3.forceManyBody().strength(-400))
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('collision', d3.forceCollide().radius(d => sizeScale(d.fanIn) + 10));

    // Create arrow marker
    svg.append('defs').append('marker')
      .attr('id', 'arrowhead')
      .attr('viewBox', '-0 -5 10 10')
      .attr('refX', 25)
      .attr('refY', 0)
      .attr('orient', 'auto')
      .attr('markerWidth', 8)
      .attr('markerHeight', 8)
      .append('svg:path')
      .attr('d', 'M 0,-5 L 10 ,0 L 0,5')
      .attr('fill', '#999')
      .style('stroke', 'none');

    // Create links
    const link = g.append('g')
      .attr('class', 'links')
      .selectAll('line')
      .data(graphData.edges)
      .join('line')
      .attr('stroke', '#999')
      .attr('stroke-opacity', 0.6)
      .attr('stroke-width', d => d.isList ? 3 : 1.5)
      .attr('stroke-dasharray', d => d.isNullable ? '5,5' : 'none')
      .attr('marker-end', 'url(#arrowhead)');

    // Create link labels
    const linkLabel = g.append('g')
      .attr('class', 'link-labels')
      .selectAll('text')
      .data(graphData.edges)
      .join('text')
      .attr('font-size', '10px')
      .attr('fill', '#666')
      .attr('text-anchor', 'middle')
      .text(d => d.fieldName + (d.isList ? '[]' : ''));

    // Create node groups
    const node = g.append('g')
      .attr('class', 'nodes')
      .selectAll('g')
      .data(graphData.nodes)
      .join('g')
      .call(d3.drag()
        .on('start', dragstarted)
        .on('drag', dragged)
        .on('end', dragended));

    // Add circles to nodes
    node.append('circle')
      .attr('r', d => sizeScale(d.fanIn))
      .attr('fill', d => colorScale(complexityScale(d.fanIn + d.fanOut)))
      .attr('stroke', '#fff')
      .attr('stroke-width', 2)
      .style('cursor', 'pointer')
      .on('click', (event, d) => {
        setSelectedNode(d);
      })
      .on('mouseover', function(event, d) {
        d3.select(this)
          .attr('stroke', '#333')
          .attr('stroke-width', 3);
      })
      .on('mouseout', function() {
        d3.select(this)
          .attr('stroke', '#fff')
          .attr('stroke-width', 2);
      });

    // Add labels to nodes
    node.append('text')
      .text(d => d.name)
      .attr('text-anchor', 'middle')
      .attr('dy', 4)
      .attr('font-size', '12px')
      .attr('font-weight', '600')
      .attr('fill', '#333')
      .style('pointer-events', 'none');

    // Simulation tick
    simulation.on('tick', () => {
      link
        .attr('x1', d => d.source.x)
        .attr('y1', d => d.source.y)
        .attr('x2', d => d.target.x)
        .attr('y2', d => d.target.y);

      linkLabel
        .attr('x', d => (d.source.x + d.target.x) / 2)
        .attr('y', d => (d.source.y + d.target.y) / 2);

      node.attr('transform', d => `translate(${d.x},${d.y})`);
    });

    // Drag functions
    function dragstarted(event, d) {
      if (!event.active) simulation.alphaTarget(0.3).restart();
      d.fx = d.x;
      d.fy = d.y;
    }

    function dragged(event, d) {
      d.fx = event.x;
      d.fy = event.y;
    }

    function dragended(event, d) {
      if (!event.active) simulation.alphaTarget(0);
      d.fx = null;
      d.fy = null;
    }

    // Cleanup
    return () => {
      simulation.stop();
    };
  }, [graphData, dimensions]);

  if (loading) {
    return (
      <div className="schema-graph loading">
        <div className="spinner"></div>
        <p>Loading schema graph...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="schema-graph error">
        <p>❌ {error}</p>
      </div>
    );
  }

  return (
    <div className="schema-graph" ref={containerRef}>
      <div className="graph-header">
        <h2>Schema Graph</h2>
        <div className="graph-legend">
          <span><span className="legend-dot small"></span> Low fan-in</span>
          <span><span className="legend-dot large"></span> High fan-in</span>
          <span><span className="legend-line solid"></span> Required</span>
          <span><span className="legend-line dashed"></span> Nullable</span>
        </div>
      </div>

      <svg
        ref={svgRef}
        width={dimensions.width}
        height={dimensions.height}
        className="graph-svg"
      />

      {selectedNode && (
        <div className="node-tooltip">
          <h4>{selectedNode.name}</h4>
          <div className="tooltip-stats">
            <div><strong>Fan-in:</strong> {selectedNode.fanIn}</div>
            <div><strong>Fan-out:</strong> {selectedNode.fanOut}</div>
            <div><strong>Total Fields:</strong> {selectedNode.totalFields}</div>
            <div><strong>Object Fields:</strong> {selectedNode.objectFields}</div>
            <div><strong>List Fields:</strong> {selectedNode.listFields}</div>
          </div>
          {selectedNode.fields && (
            <div className="tooltip-fields">
              <strong>Fields:</strong>
              <ul>
                {selectedNode.fields.slice(0, 5).map((f, i) => (
                  <li key={i}>
                    {f.name}: {f.typeName}{f.isList ? '[]' : ''}{f.isNullable ? '?' : '!'}
                  </li>
                ))}
                {selectedNode.fields.length > 5 && (
                  <li>... and {selectedNode.fields.length - 5} more</li>
                )}
              </ul>
            </div>
          )}
          <button onClick={() => setSelectedNode(null)}>Close</button>
        </div>
      )}
    </div>
  );
};

export default SchemaGraph;
